        return "scaled"
    if "pct" in params:
        return "percent"
    if "normalize" in fn_name or "due_date" in fn_name:
        return "unchanged"
    raise AssertionError("unclassified %s: %s" % (fn_name, fn_src[:80]))


MONEY_PARAMS = {"amount", "gross", "balance", "cap", "limit", "paid", "due"}
DEC_PARAMS = {"pct", "factor", "annual_rate"}


def money_lit(v, cur):
    d = Decimal(str(v))
    if d == d.quantize(Decimal("0.01")):
        text = format(d.quantize(Decimal("0.01")), "f")
