def expected_source(shp, args, params, cur, mode):
    if shp == "percent":
        return money_lit_from_decimal(q(args["amount"] * args["pct"] / 100, cur, mode), cur)
    if shp == "net":
        return money_lit_from_decimal(args["gross"] - q(args["gross"] * args["pct"] / 100, cur, mode), cur)
    if shp == "scaled":
        return money_lit_from_decimal(q(args["amount"] * args["factor"], cur, mode), cur)
