def process_file(path):
    src = path.read_text()
    tree = ast.parse(src)
    modname = None
    for node in tree.body:
        if isinstance(node, ast.ImportFrom) and node.module.startswith("ledgerly"):
            modname = node.module
    assert modname and not modname.startswith("ledgerly._gen")
    mod = importlib.import_module(modname)
    pkg = modname.split(".")[1]
    mode = PKG_MODE[pkg]

    fns = {}
    for node in ast.parse(pathlib.Path(*modname.split(".")).with_suffix(".py").read_text()).body:
        if isinstance(node, ast.FunctionDef):
            params = [a.arg for a in node.args.args]
            fns[node.name] = (shape(node.name, ast.unparse(node), params), params)

    lines = src.split("\n")
    changed = False
    for i, line in enumerate(lines):
        s = line.strip()
        if not s.startswith("self.assertEqual("):
            continue
        expr = ast.parse(s).body[0].value
        call, exp = expr.args[0], expr.args[1]
        if not isinstance(call, ast.Call):
            continue
        fname = call.func.id
        shp, params = fns[fname]
        if shp == "unchanged" or shp == "convert_float":
            continue
        sig = inspect.signature(getattr(mod, fname))
        defaults = {p.name: p.default for p in sig.parameters.values()
                    if p.default is not inspect.Parameter.empty and p.name not in ("parts",)}
        cur = None
        if "currency" in params:
            idx = params.index("currency")
            cur = ast.literal_eval(call.args[idx]) if len(call.args) > idx else sig.parameters["currency"].default
        values, new_args = convert_args(shp, call.args, params, defaults, cur)
        exp_src = expected_source(shp, values, params, cur, mode)
        indent = line[:len(line) - len(line.lstrip())]
        lines[i] = "%sself.assertEqual(%s(%s), %s)" % (indent, fname, ", ".join(new_args), exp_src)
        changed = True
    assert changed, path
    src = "\n".join(lines)

    if "Decimal(" in src and "from decimal import Decimal" not in src:
        src = src.replace("import unittest\n", "import unittest\nfrom decimal import Decimal\n", 1)
    if "Money(" in src and "from ledgerly.money import Money" not in src:
        lines = src.split("\n")
        insert_at = max(i for i, l in enumerate(lines) if l.startswith("from ledgerly"))
        if lines[insert_at] == ")":
            pass
        else:
            insert_at += 1
        lines.insert(insert_at + 1, "from ledgerly.money import Money")
        src = "\n".join(lines)
    path.write_text(src, encoding="utf-8")


for p in sorted(pathlib.Path("tests").glob("test_*.py")):
    if p.name == "test_rates.py":
